    let format = builder.intern_constant(IrConstant::String("%s:%s:%s:%s:%s:%s:%s".to_owned()));
    let values = (0..7)
        .map(|index| builder.intern_constant(IrConstant::String(format!("value-{index}"))))
        .collect::<Vec<_>>();
