fn untyped_param(builder: &mut IrBuilder, function: FunctionId, name: &str) -> LocalId {
    let local = builder.intern_local(function, name);
    builder.push_param(
        function,
        IrParam {
            name: name.to_owned(),
            local,
            required: true,
            default: None,
            type_: None,
            by_ref: false,
            variadic: false,
            attributes: Vec::new(),
        },
    );
    local
}

